public class JAverageArrayElements {
	public static void main(String[] args) {
		//Paso 1: Definir los datos y la variable que necesitamos para este programa
		int[] lst = {12, 15, 3, 4, 6, 5};
		int total = 0;
		//Paso 2: Sumar los elementos del arreglo al total acumulado uno por uno 
		for (int x : lst)
		{
		    total += x;
		}
		//Paso 3: Calcular e imprimir el promedio 
		if (lst.length == 0) {
			System.out.println("El arreglo no tiene valores.");
		} else {
			double average = (double) total / lst.length;
			System.out.println("El promedio es: " + average);	
		}
	}
}

